SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='665a1fa4-52a9-5d3c-af9e-6c0799bf6240'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('d058ca6d-844a-5275-986d-1ae58ab6a4f0','8547adce-fea1-5637-a451-040ba3bda0d7')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='665a1fa4-52a9-5d3c-af9e-6c0799bf6240'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='665a1fa4-52a9-5d3c-af9e-6c0799bf6240'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('d058ca6d-844a-5275-986d-1ae58ab6a4f0','8547adce-fea1-5637-a451-040ba3bda0d7')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='665a1fa4-52a9-5d3c-af9e-6c0799bf6240'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
