  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='unique-control-same-fingerprint-holder-commit' AND q.fingerprint='f43ec064e5dcee2e989c440a37dc2426764b274e8da1bc3f2f969dc4a9d385ab'
