  AND q.result_body='{"contract":"SH-004.v1","requestId":"unique-race-same-fingerprint-holder-commit-b","status":"ok","value":{"customerProfileId":"665a1fa4-52a9-5d3c-af9e-6c0799bf6240","userId":"f52b38af-0d56-5526-b1dc-2ce636d8dcb7","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"d058ca6d-844a-5275-986d-1ae58ab6a4f0","semanticKey":"unique-control-same-fingerprint-holder-commit","fingerprint":"f43ec064e5dcee2e989c440a37dc2426764b274e8da1bc3f2f969dc4a9d385ab","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='99b314dc-a4c1-5df4-9392-8c6278f051be' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='8437d9d9-9d46-5127-bd6b-e9401b92e0de' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"665a1fa4-52a9-5d3c-af9e-6c0799bf6240"},"prior":null,"committed":{"id":"665a1fa4-52a9-5d3c-af9e-6c0799bf6240","userId":"f52b38af-0d56-5526-b1dc-2ce636d8dcb7","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='665a1fa4-52a9-5d3c-af9e-6c0799bf6240' AND c.user_id='f52b38af-0d56-5526-b1dc-2ce636d8dcb7' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
