   AND ((o.id='1490f67e-f090-519b-b5e2-8ec17402806b' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"665a1fa4-52a9-5d3c-af9e-6c0799bf6240","userId":"f52b38af-0d56-5526-b1dc-2ce636d8dcb7","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='3e1b2612-e3dc-5339-8178-cbff522eeec5' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"f52b38af-0d56-5526-b1dc-2ce636d8dcb7","track":"customer","customerProfileId":"665a1fa4-52a9-5d3c-af9e-6c0799bf6240","sourceCreationRevision":"0","sourceCreationReceipt":"d058ca6d-844a-5275-986d-1ae58ab6a4f0","semanticKey":"customer_buyer_profile/665a1fa4-52a9-5d3c-af9e-6c0799bf6240/default-free-enrollment/v1"}'::jsonb)))=2));
